        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(-1, True)

    def test_day_seven_rejected(self):
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, True)

    def test_invalid_day_rejected_even_when_disabled(self):
        # 驗 day 須先於 paused 判斷
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, False)

    def test_string_day_rejected(self):
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route("1", True)

